"use client";

import { useTranslations } from "next-intl";
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { useCooldown } from "@/components/ui/use-cooldown";

const POLL_MS = 1500;
const MAX_POLLS = 20;

/**
 * "Your angle": queues a personal angle (generated by an Inngest job, plan §6) and polls
 * until it is ready. Shows an error when generation is unavailable or the daily limit hit.
 */
export function AngleButton({
  storyId,
  nicheId,
}: {
  storyId: string;
  nicheId: string;
}) {
  const t = useTranslations("radar.angle");
  const [state, setState] = useState<"idle" | "loading" | "error" | "limit">(
    "idle",
  );
  const [angle, setAngle] = useState<string | null>(null);
  const url = `/api/radar/${storyId}/angle?niche=${nicheId}`;
  const { cooling, start: startCooldown } = useCooldown(4000);

  async function request() {
    startCooldown();
    setState("loading");
    try {
      const res = await fetch(url, { method: "POST" });
      if (res.status === 429) return setState("limit");
      if (!res.ok) return setState("error");
      const body = (await res.json()) as { angle?: string | null };
      if (body.angle) {
        setAngle(body.angle);
        return setState("idle");
      }
      for (let i = 0; i < MAX_POLLS; i++) {
        await new Promise((r) => setTimeout(r, POLL_MS));
        const poll = await fetch(url);
        if (!poll.ok) return setState("error");
        const data = (await poll.json()) as { angle?: string | null };
        if (data.angle) {
          setAngle(data.angle);
          return setState("idle");
        }
      }
      setState("error");
    } catch {
      // Network failure or an aborted request: stop the spinner, let the user retry.
      setState("error");
    }
  }

  if (angle) {
    return (
      <p className="border-brand/30 bg-brand/5 rounded-md border p-3 text-[16.25px]">
        <span className="font-medium">{t("label")}</span> {angle}
      </p>
    );
  }
  return (
    <div className="flex items-center gap-2">
      <Button
        size="sm"
        variant="outline"
        onClick={request}
        disabled={state === "loading" || cooling}
      >
        {state === "loading" ? t("loading") : t("cta")}
      </Button>
      {state === "error" && (
        <span role="alert" className="text-danger text-xs">
          {t("error")}
        </span>
      )}
      {state === "limit" && (
        <span role="alert" className="text-danger text-xs">
          {t("limit")}
        </span>
      )}
    </div>
  );
}
